const users = { 'admin@admin.com': 'b80d6dc4be890766e16b' }; // Usuário de teste
const sessions = {};

function parseCookies(cookieHeader) {
    const cookies = {};
    if (!cookieHeader) return cookies;

    cookieHeader.split(';').forEach(cookie => {
        const [parts] = cookie.split('=');
        const name = parts.trim();
        const value = cookie.substring(name.length + 1).trim();
        if (name) cookies[name] = decodeURIComponent(value);
    });
    return cookies;
}

export function checkAuth({ req, res }) {
    const cookies = parseCookies(req.headers.cookie);
    const sessionId = cookies['sessionId'];

    // Verifica se o ID existe na nossa memória
    if (sessionId && sessions[sessionId]) {
        req.user = sessions[sessionId]; // Injeta o usuário na requisição
        return;
    } else {
        res.status(401).send('<h1>Acesso negado. Faça <a href="/login">login</a>.</h1>');
    }
}

export function login(req, res) {
    /**
     * @register_router login
     * @method POST
     */

    // return process.env.AUTH_ENV_SECRET_SESSION;
    const { email, password } = req.body;

    // Valida as credenciais
    if (users[email] && users[email] === password) {
        // Gera um ID de sessão único "artesanal"
        const sessionId = Math.random().toString(36).substring(2) + Date.now().toString(36);

        // Salva a sessão na memória do servidor
        sessions[sessionId] = { email, loginAt: new Date() };

        // Envia o cookie para o navegador via HTTP Header nativo
        // HttpOnly impede que scripts maliciosos (XSS) acessem o cookie
        res.setHeader('Set-Cookie', `sessionId=${sessionId}; HttpOnly; Path=/; SameSite=Strict`);

        return res.redirect('/dashboard');
    }

    res.status(400).send('Usuário ou senha inválidos. <a href="/login">Tentar novamente</a>');
};

export function list() {
    /**
     * @register_router get
     * @method GET
     */

    return sessions;
}
